import java.util.ArrayList;
import java.util.List;

public class StateBacktracking {
    static char[][] board = {
        "ABCE".toCharArray(),
        "SFCS".toCharArray(),
        "ADEE".toCharArray(),
    };

    static boolean exists(String word) {
        for (int r = 0; r < board.length; r++)
            for (int c = 0; c < board[0].length; c++)
                if (dfs(word, 0, r, c)) return true;
        return false;
    }

    static boolean dfs(String word, int i, int r, int c) {
        if (i == word.length()) return true;
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) return false;
        if (board[r][c] != word.charAt(i)) return false;
        char saved = board[r][c];
        board[r][c] = '*';                                   // mark: used in this word
        boolean found = dfs(word, i + 1, r + 1, c) || dfs(word, i + 1, r - 1, c)
                || dfs(word, i + 1, r, c + 1) || dfs(word, i + 1, r, c - 1);
        board[r][c] = saved;                                 // restore on every path
        return found;
    }

    static void subsets(int[] nums, int start, List<Integer> path, List<List<Integer>> leaky, List<List<Integer>> safe) {
        leaky.add(path);                                     // BUG: the shared list itself
        safe.add(new ArrayList<>(path));                     // a snapshot
        for (int i = start; i < nums.length; i++) {
            path.add(nums[i]);
            subsets(nums, i + 1, path, leaky, safe);
            path.remove(path.size() - 1);
        }
    }

    public static void main(String[] args) {
        for (String word : new String[]{"SEE", "ABCCED", "ABCB"}) {
            System.out.println(word + ": " + (exists(word) ? "found" : "not found"));
        }
        System.out.print("board afterwards:");
        for (char[] row : board) System.out.print(" " + new String(row));
        System.out.println();

        List<List<Integer>> leaky = new ArrayList<>(), safe = new ArrayList<>();
        subsets(new int[]{1, 2}, 0, new ArrayList<>(), leaky, safe);
        System.out.println("stored the shared path: " + leaky);
        System.out.println("stored copies:          " + safe);
    }
}

