public class ConstraintSearch {
    static int[][] grid = {
        {1, 0, 0, 0},
        {0, 0, 3, 0},
        {0, 4, 0, 0},
        {0, 0, 0, 2},
    };
    static boolean[][] rowHas = new boolean[4][5], colHas = new boolean[4][5], boxHas = new boolean[4][5];

    static int box(int r, int c) { return (r / 2) * 2 + c / 2; }

    static void set(int r, int c, int d, boolean on) {
        grid[r][c] = on ? d : 0;
        rowHas[r][d] = colHas[c][d] = boxHas[box(r, c)][d] = on;
    }

    static boolean solve(int cell) {
        if (cell == 16) return true;                        // every cell filled
        int r = cell / 4, c = cell % 4;
        if (grid[r][c] != 0) return solve(cell + 1);        // given clue: skip
        for (int d = 1; d <= 4; d++) {
            if (rowHas[r][d] || colHas[c][d] || boxHas[box(r, c)][d]) continue;   // constraint
            set(r, c, d, true);                             // choose
            System.out.println("  ".repeat(Math.min(cell, 6)) + "(" + r + "," + c + ") = " + d);
            if (solve(cell + 1)) return true;               // explore
            set(r, c, d, false);                            // unchoose
            System.out.println("  ".repeat(Math.min(cell, 6)) + "(" + r + "," + c + ") undo " + d);
        }
        return false;                                       // no digit fits: back up
    }

    public static void main(String[] args) {
        for (int r = 0; r < 4; r++)
            for (int c = 0; c < 4; c++)
                if (grid[r][c] != 0) set(r, c, grid[r][c], true);
        System.out.println(solve(0) ? "solved:" : "no solution");
        for (int[] row : grid) {
            StringBuilder line = new StringBuilder(" ");
            for (int v : row) line.append(" ").append(v);
            System.out.println(line);
        }
    }
}

